ALTER TABLE "standalone_license_issuances" ADD CONSTRAINT "standalone_license_issuances_shape_check" CHECK ("standalone_license_issuances"."sequence" > 0 and "standalone_license_issuances"."grace_days" between 0 and 60 and "standalone_license_issuances"."plan" in ('demo','subscription') and ("standalone_license_issuances"."plan" <> 'demo' or "standalone_license_issuances"."grace_days" = 0) and "standalone_license_issuances"."sha256" ~ '^[0-9a-f]{64}$' and length(btrim("standalone_license_issuances"."kid")) between 1 and 128 and octet_length("standalone_license_issuances"."compact") between 1 and 16384 and "standalone_license_issuances"."entitlement_revision" >= 0 and "standalone_license_issuances"."valid_until_reason" in ('subscription_end','entitlement_reduction','one_year_cap','offline_term','demo_term') and "standalone_license_issuances"."source" in ('subscription','offline','offline_assignments','offline_demo') and (("standalone_license_issuances"."source" = 'offline') = ("standalone_license_issuances"."valid_until_reason" = 'offline_term')) and (("standalone_license_issuances"."source" = 'offline_demo') = ("standalone_license_issuances"."valid_until_reason" = 'demo_term')) and ("standalone_license_issuances"."source" not in ('offline','offline_assignments') or "standalone_license_issuances"."plan" = 'subscription') and ("standalone_license_issuances"."source" <> 'offline_demo' or ("standalone_license_issuances"."plan" = 'demo' and "standalone_license_issuances"."valid_until" - "standalone_license_issuances"."valid_from" <= interval '45 days')) and ("standalone_license_issuances"."source" not in ('subscription','offline') or "standalone_license_issuances"."source_assignments" is null) and ("standalone_license_issuances"."source" <> 'offline_assignments' or "standalone_license_issuances"."source_assignments" is not null) and ("standalone_license_issuances"."source_assignments" is null or (jsonb_typeof("standalone_license_issuances"."source_assignments") = 'array' and jsonb_array_length("standalone_license_issuances"."source_assignments") between 1 and 65)));